(function(E){ const x = E["sales-m3"] = E["sales-m3"] || {units:{}}; x.units["sales-3-2"] = {"grammar":{"id":"c-sales-3-2-g","level":"B1","course":"sales","unit":"sales-3-2","title":"Trading in a negotiation: If you signed..., we could...","titleTr":"Pazarlıkta takas: If you signed..., we could...","titleFa":"بده‌بستان در مذاکره: If you signed..., we could...","formsTable":{"headers":{"en":["If-part (past)","Other part (would / could)"],"tr":["if kısmı (geçmiş)","Diğer kısım (would / could)"],"fa":["بخش if (گذشته)","بخش دیگر (would / could)"]},"rows":[["If you signed for a year,","we could offer EUR 39."],["If we gave you 60 days,","we would need a higher price."],["If you paid 30% now,","we could start next week."],["What if we","split the order into three deliveries?"]]},"wrong":"If we would give you 60 days, we would need a higher price.","right":"If we gave you 60 days, we would need a higher price.","blank":{"sentence":"If you ___ a one-year contract, we could offer EUR 39.","word":"signed","distractors":["signing","to sign"]},"wrong2":"What if we would split the order into three deliveries?","right2":"What if we split the order into three deliveries?","blank2":{"sentence":"If we ___ the price, would you commit to a full year?","word":"lowered","distractors":["lowering","to lower"]},"expParts":{"tryFrom":"blank","rule":[{"en":"If + past, then would or could + verb.","tr":"If + geçmiş zaman, sonra would ya da could + fiil.","fa":"در بخش if فعل گذشته می‌آید و در بخش دوم would یا could با فعل ساده.","ex":"If you signed for a year, we could offer EUR 39."},{"en":"Past form, present meaning: an idea, not a promise.","tr":"Geçmiş biçim, şimdiki anlam: bir söz değil, bir fikir.","fa":"فعل گذشته است، ولی منظورت زمان حال است: فقط ایده‌ای را مطرح می‌کنی و قولی نمی‌دهی.","ex":"If we gave you 60 days, ..."},{"en":"No would in the if-part.","tr":"if kısmında would yok.","fa":"در بخش if کلمه‌ی would نمی‌آید.","ex":"If we gave..., not If we would give"},{"en":"What if we + past? suggests a trade softly.","tr":"What if we + geçmiş? bir takası yumuşakça önerir.","fa":"با What if we و فعل گذشته، بده‌بستان را نرم پیشنهاد می‌کنی.","ex":"What if we split the order into three deliveries?"}],"test":{"en":"Is there would in your if-part? Move it to the other half of the sentence.","tr":"if kısmında would var mı? Onu cümlenin diğer yarısına taşı.","fa":"در بخش if، would داری؟ آن را به بخش دیگر جمله ببر."},"contrast":{"en":"Turkish uses '-sak' ('Fiyatı düşürsek imzalar mısınız?') and Persian «اگر ... می‌کردیم» or «اگر ... کنیم», with no past-for-present rule. So learners put would in both halves. English: past in the if-part, would only in the other.","tr":"Türkçede '-sak' kullanırız: 'Fiyatı düşürsek imzalar mısınız?' Burada şimdi için geçmiş biçim kuralı yok; bu yüzden İngilizcede iki yarıya da would konuyor. İngilizcede if kısmına geçmiş biçim, would yalnızca diğer kısma gelir.","fa":"در فارسی می‌گوییم «اگر قیمت را کم کنیم، امضا می‌کنید؟» یا «اگر کم می‌کردیم...». قاعده‌ی «گذشته برای حال» را به این شکل نداریم؛ برای همین خیلی از ما در هر دو بخش جمله would می‌گذاریم. در انگلیسی بخش if گذشته است و would فقط در بخش دیگر می‌آید."}},"errorWatch":[{"find":["if we would","what if we would","if you would sign","if you would pay","if you would order","if they would sign"],"fix":{"en":"No would in the if-part: 'If we gave you 60 days, we would...'.","tr":"if kısmında would yok: 'If we gave you 60 days, we would...'.","fa":"در بخش if، would نمی‌آید: «If we gave you 60 days, we would...»"}}]},"b2":{"id":"c-sales-3-2-b2","level":"B2","track":"B2","course":"sales","unit":"sales-3-2","title":"Testing an idea: Suppose we..., If we were to...","titleTr":"Bir fikri yoklamak: Suppose we..., If we were to...","titleFa":"سنجیدن یک ایده: Suppose we... و If we were to...","formsTable":{"headers":{"en":["Opener","Example"],"tr":["Giriş","Örnek"],"fa":["شروع","مثال"]},"rows":[["Suppose / Supposing + past","Suppose we delivered in three parts, would that help?"],["If + were to + base verb","If we were to offer 60 days, the price would be EUR 41."],["What would you say if + past","What would you say if we added your label?"]]},"wrong":"Suppose we will deliver in three parts, would that help?","right":"Suppose we delivered in three parts, would that help?","blank":{"sentence":"If we were ___ 60 days, the price would be EUR 41.","word":"to offer","distractors":["offer","offering"]},"wrong2":"If we were to offered free samples, would you test them?","right2":"If we were to offer free samples, would you test them?","blank2":{"sentence":"___ we delivered the order in two parts, would that work?","word":"Suppose","distractors":["Unless","Despite"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"Suppose + past = 'Let's imagine...' (like if).","tr":"Suppose + geçmiş = 'Diyelim ki...' (if gibi).","fa":"بعد از Suppose فعل گذشته می‌آید و معنایش «فرض کنیم...» است.","ex":"Suppose we delivered in three parts, ..."},{"en":"If + were to + base verb: a distant, safe idea.","tr":"If + were to + yalın fiil: uzak ve güvenli bir fikir.","fa":"بعد از If we were to فعل ساده می‌آید و ایده را دور و بی‌خطر نشان می‌دهد.","ex":"If we were to offer 60 days, ..."},{"en":"would goes in the other half, never after Suppose.","tr":"would diğer yarıya gider, asla Suppose'tan sonra değil.","fa":"کلمه‌ی would به بخش دیگر جمله می‌رود و هرگز بعد از Suppose نمی‌آید.","ex":"..., would that help?"}],"test":{"en":"Replace Suppose with If. Does the sentence still work? Then your verb form is right.","tr":"Suppose yerine If koy. Cümle hâlâ doğru mu? O zaman fiil biçimin doğru.","fa":"Suppose را با If عوض کن. جمله هنوز درست است؟ پس شکل فعلت درست است."},"contrast":{"en":"Turkish 'Diyelim ki üç parti hâlinde teslim ettik' and Persian «فرض کنیم در سه نوبت تحویل بدهیم» use a past or subjunctive verb, so the idea is close. English Suppose + past and were to keep the idea at a safe distance.","tr":"Türkçede 'Diyelim ki üç parti hâlinde teslim ettik, işinize yarar mı?' deriz. İngilizcede Suppose + geçmiş zaman ve were to, fikri güvenli bir mesafede tutar; ardından would gelir.","fa":"در فارسی می‌گوییم «فرض کنیم در سه نوبت تحویل بدهیم، کمکی می‌کند؟». در انگلیسی Suppose با فعل گذشته و were to ایده را دور و بی‌خطر نشان می‌دهند و بعدش would می‌آید."}},"errorWatch":[{"find":["suppose we will","supposing we will","suppose you will","were to offered","were to gave","were to signed","were to delivered"],"fix":{"en":"Suppose + past; were to + base verb: 'Suppose we delivered...', 'If we were to offer...'.","tr":"Suppose + geçmiş zaman; were to + yalın fiil: 'Suppose we delivered...', 'If we were to offer...'.","fa":"بعد از Suppose فعل گذشته می‌آید و بعد از were to فعل ساده: «Suppose we delivered...» و «If we were to offer...»"}}],"useIn":{"en":"B2: test one idea with Suppose or If we were to before you offer it.","tr":"B2: bir fikri sunmadan önce Suppose ya da If we were to ile yokla.","fa":"مسیر B2: پیش از پیشنهاد دادن یک ایده، آن را با Suppose یا If we were to بسنج."},"exitItem":{"from":"sales-3-2","kind":"blank","prompt":"If we were ___ the price by 5%, would you sign today?","options":["to cut","cut","cuts"],"correct":0,"why":{"en":"to cut: 'If we were to' + verb tests an idea. 'Were cut' would be passive, and 'were cuts' is not English.","tr":"to cut: 'If we were to' + fiil bir fikri dener. 'Were cut' edilgen olur; 'were cuts' İngilizce değildir.","fa":"to cut درست است، چون If we were to و فعل یک ایده را امتحان می‌کند. were cut مجهول می‌شود و were cuts انگلیسی نیست."}}},"vocab":{"id":"c-sales-3-2-v","level":"B1","category":"vocab","course":"sales","unit":"sales-3-2","goals":["career"],"title":{"en":"Negotiating","tr":"Pazarlık","fa":"مذاکره"},"cards":[{"word":"negotiate","sentence":"We negotiated for two hours and agreed on payment.","gap":"negotiated","accept":["negotiated","negotiate"],"meaning":{"en":"To discuss until both sides agree.","tr":"pazarlık etmek, müzakere etmek.","fa":"مذاکره کردن"}},{"word":"concession","sentence":"A longer payment period is a big concession.","meaning":{"en":"Something you give up to reach an agreement.","tr":"ödün, taviz.","fa":"امتیاز (چیزی که برای توافق از آن می‌گذری)"}},{"word":"trade","sentence":"We traded a lower price for a bigger order.","gap":"traded","accept":["traded","trade"],"meaning":{"en":"To give one thing to get another.","tr":"takas etmek, karşılığında vermek.","fa":"بده‌بستان کردن؛ چیزی دادن و چیزی گرفتن"}},{"word":"commit","sentence":"Can you commit to 300 cartons a month?","meaning":{"en":"To promise to do something for a time.","tr":"taahhüt etmek, söz vermek.","fa":"متعهد شدن"}},{"word":"contract","sentence":"The contract runs for one year.","meaning":{"en":"A written legal agreement.","tr":"sözleşme.","fa":"قرارداد"}},{"word":"terms","sentence":"Let's go through the terms again.","meaning":{"en":"The conditions of an agreement.","tr":"koşullar.","fa":"شرایط (قرارداد)"}},{"word":"margin","sentence":"At that price there is no margin left.","meaning":{"en":"The money left after your costs.","tr":"kâr marjı","fa":"حاشیه‌ی سود"}},{"word":"approve","sentence":"My director has to approve the price.","meaning":{"en":"To say officially that something is OK.","tr":"onaylamak.","fa":"تأیید کردن"}},{"word":"split","sentence":"We could split the difference.","meaning":{"en":"To divide into parts.","tr":"bölmek.","fa":"تقسیم کردن"}},{"word":"walk away","sentence":"If the price falls below our limit, we walk away.","meaning":{"en":"To leave a deal you cannot accept.","tr":"masadan kalkmak, anlaşmadan vazgeçmek.","fa":"کنار کشیدن از معامله‌ای که نمی‌شود پذیرفت"}}]},"judge":{"id":"c-sales-3-2-j","course":"sales","unit":"sales-3-2","type":"judge","title":{"en":"Trade or gift?","tr":"Takas mı, hediye mi?","fa":"بده‌بستان یا هدیه؟"},"prompt":"A buyer of olive oil asks for a lower price. Four replies.","parts":["Gets something back","Uses if","Keeps the limit"],"instruction":{"en":"Tap what each reply does. The best reply does all three.","tr":"Her cevabın ne yaptığına dokun. En iyi cevap üçünü de yapar.","fa":"روی کاری که هر جواب می‌کند بزن. بهترین جواب هر سه را دارد."},"items":[{"by":"New rep","answer":"OK, no problem. I can go down to EUR 38, and that's really my limit.","present":[],"fix":{"en":"A gift, and you told them your limit. Ask for something back: 'If you ordered 300 tins, we could look at the price.'","tr":"Bir hediye ve sınırını da söyledin. Karşılığında bir şey iste: 'If you ordered 300 tins, we could look at the price.'","fa":"هدیه است و حد نهایی‌ات را هم گفتی. در عوضش چیزی بخواه: «If you ordered 300 tins, we could look at the price.»"}},{"by":"Sales rep","answer":"No. Our price is our price.","present":["Keeps the limit"],"fix":{"en":"You kept your price, but you closed the talk. Offer a trade: 'If you paid in advance, we could...'","tr":"Fiyatını korudun ama konuşmayı kapattın. Takas öner: 'If you paid in advance, we could...'","fa":"قیمتت را نگه داشتی، ولی گفت‌وگو را بستی. بده‌بستان پیشنهاد کن: «If you paid in advance, we could...»"}},{"by":"AI tool","answer":"If it were possible for us to explore flexibility, we would be happy to consider offering EUR 38 at this time.","present":["Uses if"],"fix":{"en":"Long, and it still gives EUR 38 for nothing. Say what you need in return, in few words.","tr":"Uzun ve hâlâ EUR 38'i karşılıksız veriyor. Karşılığında ne istediğini az sözle söyle.","fa":"بلند است و هنوز ۳۸ یورو را مجانی می‌دهد. با کلمه‌های کم بگو در عوضش چه می‌خواهی."}},{"by":"Good model","answer":"If you ordered 300 tins, we could offer EUR 39. If you stay at 100, the price stays at EUR 42. Which works better for you?","present":["Gets something back","Uses if","Keeps the limit"],"fix":null}]},"speaking":{"id":"sales-3-2","course":"sales","unit":"sales-3-2","topic":{"en":"Trading, not giving","tr":"Vermek değil, takas etmek","fa":"بده‌بستان، نه بخشیدن"},"warmup":{"en":"What is cheap for you to give but valuable for your buyer?","tr":"Vermesi sana ucuza gelen ama alıcın için değerli olan şey ne?","fa":"چه چیزی برای تو کم‌هزینه است، ولی برای خریدارت ارزش دارد؟"},"questions":[{"en":"The buyer says: 'I need 10% off.' Ask what matters most, then make one trade with if.","tr":"Alıcı diyor ki: 'I need 10% off.' En önemli şeyi sor, sonra if ile bir takas yap.","fa":"خریدار می‌گوید: «I need 10% off.» بپرس چه چیزی مهم‌تر است، بعد با if یک بده‌بستان کن."},{"en":"The buyer asks for 60 days to pay. Answer with a condition.","tr":"Alıcı ödeme için 60 gün istiyor. Bir koşulla cevap ver.","fa":"خریدار برای پرداخت ۶۰ روز مهلت می‌خواهد. با یک شرط جواب بده."},{"en":"You have agreed. Repeat the deal in two sentences, and say you will send it in writing.","tr":"Anlaştınız. Anlaşmayı iki cümleyle tekrar et ve yazılı göndereceğini söyle.","fa":"توافق کرده‌اید. توافق را در دو جمله تکرار کن و بگو کتبی می‌فرستی."}],"followups":[{"en":"What is your own walk-away point on your product? What would you do instead?","tr":"Kendi ürününde vazgeçme noktan ne? Onun yerine ne yapardın?","fa":"حد نهایی‌ات برای محصول خودت چیست؟ اگر به توافق نرسیدی، به‌جایش چه می‌کنی؟"}],"expressions":[{"phrase":"What matters most to you?","meaning":{"en":"Finds what to trade.","tr":"Neyin takas edileceğini bulur.","fa":"معلوم می‌کند چه چیزی را بده‌بستان کنی."}},{"phrase":"If you ..., we could ...","meaning":{"en":"Offers a trade.","tr":"Takas önerir.","fa":"بده‌بستان پیشنهاد می‌کند."}},{"phrase":"So, to confirm, ...","meaning":{"en":"Repeats what you agreed.","tr":"Anlaşılanı tekrar eder.","fa":"توافق را تکرار می‌کند."}}],"model":"I hear you. What matters most to you: the price, the delivery date or the payment terms? I see. If you ordered three hundred tins, we could offer thirty-nine euros. And if you paid half in advance, we could ship a week earlier. So, to confirm: three hundred tins at thirty-nine euros, half in advance. I'll send that in writing today.","selfCheck":[{"en":"I asked what matters most before I offered anything.","tr":"Bir şey önermeden önce en önemli şeyi sordum.","fa":"قبل از هر پیشنهادی پرسیدم چه چیزی مهم‌تر است."},{"en":"I gave nothing without getting something.","tr":"Karşılığını almadan bir şey vermedim.","fa":"بدون گرفتن چیزی، چیزی ندادم."},{"en":"I used past + would or could, with no would after if.","tr":"Geçmiş zaman + would ya da could kullandım, if'ten sonra would kullanmadım.","fa":"در بخش if فعل گذشته و در بخش دیگر would یا could به کار بردم و بعد از if، would نیاوردم."},{"en":"I repeated the deal at the end.","tr":"Sonunda anlaşmayı tekrar ettim.","fa":"در پایان توافق را تکرار کردم."}]},"writing":{"id":"c-sales-3-2-w","course":"sales","unit":"sales-3-2","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your negotiation plan","tr":"Pazarlık planın","fa":"برنامه‌ی مذاکره‌ی تو"},"portfolio":null,"prompt":{"en":"Plan a real deal, or a buyer who wants 10% off 100 tins of olive oil at EUR 42 a tin; your limit is EUR 38.50, and a shop group in Poland also wants the oil (70-100 words). Write: your target, your limit, your plan if there's no deal, two things you can trade, then the two trade sentences you will say, with If you..., we could....","tr":"Gerçek bir anlaşmayı ya da tanesi 42 euro olan 100 teneke zeytinyağında %10 indirim isteyen bir alıcıyı planla; sınırın 38,50 euro ve Polonya'daki bir mağaza grubu da bu yağı istiyor (70-100 kelime). Şunları yaz: hedefin, sınırın, anlaşma olmazsa planın, takas edebileceğin iki şey ve söyleyeceğin iki takas cümlesi (If you..., we could...).","fa":"برای یک معامله‌ی واقعی برنامه بریز، یا برای خریداری که برای ۱۰۰ حلب روغن زیتون ۴۲ یورویی ۱۰ درصد تخفیف می‌خواهد؛ حد نهایی‌ات ۳۸٫۵۰ یورو است و یک گروه فروشگاهی در لهستان هم این روغن را می‌خواهد (۷۰ تا ۱۰۰ کلمه). بنویس: هدفت، حد نهایی‌ات، برنامه‌ات اگر توافق نشد، دو چیز برای بده‌بستان، و دو جمله‌ی بده‌بستانی که می‌گویی (If you..., we could...)."},"model":"Target: EUR 41 a tin. Limit: EUR 38.50.\nNo deal: I sell the same oil to the shop group in Poland.\nI can trade: a bigger order, faster payment.\n\nWhat I will say:\nIf you ordered 300 tins, we could offer EUR 39.\nIf you paid half in advance, we could ship one week earlier.\nIf neither works, I will thank them and keep the price at EUR 42, because the Polish offer is better.","frame":"Target: ___. Limit: ___.\nNo deal: I ___.\nI can trade: ___, ___.\n\nWhat I will say:\nIf you ___, we could ___.\nIf you ___, we could ___.\nIf neither works, I will ___.","words":[{"word":"Limit"},{"word":"If you ordered"},{"word":"we could"}],"minWords":55,"minSentences":4,"rubric":["Task done: target, limit, plan if no deal, two trades, two sentences","Organised: the plan first, the words second","Language: if + past, could or would in the other part","Tone: firm and fair; nothing is given for free"],"rubricI18n":{"tr":["Görev: hedef, sınır, anlaşma olmazsa plan, iki takas, iki cümle","Düzen: önce plan, sonra söylenecekler","Dil: if + geçmiş zaman, öbür tarafta could ya da would","Üslup: kararlı ve adil; hiçbir şey bedava verilmiyor"],"fa":["کامل بودن کار: هدف، حد نهایی، برنامه‌ی جایگزین، دو بده‌بستان، دو جمله","نظم: اول برنامه، بعد جمله‌ها","زبان: فعل گذشته بعد از if، و در بخش دیگر could یا would","لحن: محکم و منصفانه؛ هیچ چیز را مجانی نمی‌دهی"]}},"exit":{"id":"c-sales-3-2-x","course":"sales","unit":"sales-3-2","type":"exit","items":[{"from":"sales-3-2","kind":"blank","prompt":"If you ___ half in advance, we could ship a week earlier.","options":["pay","paid","would pay"],"correct":1,"point":2,"why":{"en":"paid: 'we could' shows a possible deal, so 'if' takes the past. 'Pay' goes with 'we can', and 'would pay' never follows if here.","tr":"paid: 'we could' olası bir anlaşmayı gösterir, bu yüzden 'if' geçmiş zaman alır. 'Pay' 'we can' ile gelir; 'would pay' burada if'ten sonra gelmez.","fa":"paid درست است، چون we could یک معامله‌ی احتمالی را نشان می‌دهد و بعد از if گذشته می‌آید. pay با we can می‌آید و would pay اینجا بعد از if نمی‌آید."}},{"from":"sales-3-2","kind":"mcq","prompt":"Which line is a trade, not a gift?","options":["We can lower it a little for you. Is that OK with you?","If you doubled the order, we could lower the price.","Our limit is EUR 38, but we may go lower next year."],"correct":1,"point":1,"why":{"en":"It asks for something back: a bigger order for a lower price. The other two give a cut and get nothing.","tr":"Karşılığında bir şey ister: daha düşük fiyata karşı daha büyük sipariş. Diğer ikisi indirim verir, hiçbir şey almaz.","fa":"در عوض چیزی می‌خواهد: سفارش بزرگ‌تر در برابر قیمت پایین‌تر. دو گزینه‌ی دیگر تخفیف می‌دهند و چیزی نمی‌گیرند."}},{"from":"sales-3-2","kind":"mcq","prompt":"What should you know before you start negotiating?","options":["Your limit and your plan if there is no deal","The buyer's family, hobbies and date of birth","Only your first price, and nothing else at all"],"correct":0,"point":1,"why":{"en":"Your limit and your plan if there is no deal: they stop you agreeing to a bad price. Personal details don't help, and one price alone leaves no room.","tr":"Sınırın ve anlaşma olmazsa planın: kötü bir fiyata evet demeni engeller. Kişisel bilgiler işe yaramaz; tek bir fiyat da hareket alanı bırakmaz.","fa":"حد خودت و برنامه‌ات اگر معامله نشد؛ این‌ها نمی‌گذارند به قیمت بد بله بگویی. اطلاعات شخصی کمکی نمی‌کند و فقط یک قیمت هم جایی برای مذاکره نمی‌گذارد."}},{"from":"sales-3-1","kind":"mcq","prompt":"A buyer says: \"You're 15% more expensive.\" What do you do first?","options":["Agree with what is true, then ask: compared with what?","Say that your competitors use cheaper materials.","Offer 5% off, so the buyer stays in the talk."],"correct":0,"point":1,"why":{"en":"Agree with what is true, then ask 'compared with what?': you learn what they compare. Blaming rivals or a quick 5% skips that.","tr":"Doğru olanı kabul et, sonra 'compared with what?' diye sor: neyle karşılaştırdıklarını öğrenirsin. Rakipleri suçlamak ya da hemen %5 vermek bunu atlar.","fa":"اول چیزی را که درست است بپذیر و بعد بپرس «compared with what?»؛ این‌طوری می‌فهمی با چه مقایسه می‌کند. بد گفتن از رقیب یا ۵ درصد تخفیف فوری این قدم را جا می‌اندازد."}},{"from":"sales-2-3","kind":"blank","prompt":"We can't load the truck unless the customs papers ___ ready.","options":["aren't","are","won't be"],"correct":1,"point":2,"why":{"en":"are: after 'unless', use the present with no 'not'. 'Aren't' makes a double negative, and 'won't be' is wrong after unless.","tr":"are: 'unless'ten sonra geniş zaman gelir, olumsuzluk eklenmez. 'Aren't' çift olumsuz yapar; 'won't be' unless'ten sonra yanlıştır.","fa":"are درست است، چون بعد از unless زمان حال می‌آید و منفی نمی‌شود. aren't منفیِ دوتایی می‌سازد و won't be بعد از unless غلط است."}},{"from":"sales-1-1","kind":"blank","prompt":"The sacks are waterproof, which ___ they stay dry at the port.","options":["means","mean","meaning"],"correct":0,"point":2,"why":{"en":"means: 'which' refers to the whole fact, so the verb is singular. 'Mean' needs a plural subject; 'meaning' is not a full verb.","tr":"means: 'which' tüm bilgiyi kasteder, fiil tekildir. 'Mean' çoğul özne ister; 'meaning' tam fiil değildir.","fa":"means درست است، چون which به کل آن واقعیت برمی‌گردد و فعلش مفرد است. mean فاعل جمع می‌خواهد و meaning فعل کامل نیست."}}]},"explain":{"id":"c-sales-3-2-e","course":"sales","unit":"sales-3-2","type":"explain","level":"B1","title":{"en":"Negotiate: trade, never give","tr":"Pazarlık: takas et, bedava verme","fa":"مذاکره: بده‌بستان کن، مجانی نده"},"objective":{"en":"After this lesson, you can prepare a negotiation and trade one thing for another, so that you never give anything for free.","tr":"Bu dersin sonunda bir pazarlığa hazırlanabilecek ve bir şeyi başka bir şey karşılığında vererek hiçbir şeyi bedavaya vermeden uzlaşabileceksin.","fa":"بعد از این درس می‌توانی برای مذاکره آماده شوی و چیزی را در برابر چیز دیگری بدهی، تا هیچ چیز را مجانی ندهی."},"hook":{"en":"In a negotiation, give something only when you get something back. Every free concession teaches the buyer to ask for another one.","tr":"Pazarlıkta yalnızca karşılığında bir şey alırsan bir şey ver. Bedava verilen her ödün, alıcıya bir tane daha istemeyi öğretir.","fa":"در مذاکره فقط وقتی چیزی بده که در عوض چیزی بگیری. هر امتیاز مجانی به خریدار یاد می‌دهد یکی دیگر هم بخواهد."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Prepare, then trade","tr":"Hazırlan, sonra takas et","fa":"آماده شو، بعد بده‌بستان کن"},"steps":[{"en":"Know your target, your limit and your no-deal plan, so pressure can't change your decision.","tr":"Hedefini, sınırını ve anlaşma olmazsa planını bil; böylece baskı kararını değiştiremez.","fa":"قبل از شروع مذاکره سه چیز را بدان: هدفت، حد نهایی‌ات و اینکه اگر توافق نشد چه می‌کنی. این‌طوری فشار تصمیمت را عوض نمی‌کند.","ex":"Limit: EUR 38. No deal? Sell to the Polish buyer."},{"en":"List what is cheap for you but valuable for them. These are your best trades.","tr":"Sana ucuza gelen ama onlar için değerli olan şeyleri listele. En iyi takasların bunlardır.","fa":"چیزهایی را فهرست کن که برای تو کم‌هزینه و برای آن‌ها ارزشمندند. بهترین بده‌بستان‌هایت همین‌هاست.","ex":"Their label on the carton. Delivery in two parts."},{"en":"Ask what matters most to them, and why, so you trade the right thing.","tr":"Onlar için en önemli şeyin ne olduğunu ve nedenini sor; doğru şeyi takas et.","fa":"بپرس چه چیزی برایشان مهم‌تر است و چرا، تا چیز درست را بده‌بستان کنی.","ex":"What matters most: price, date or payment terms?"},{"en":"Trade with if. It makes your offer depend on theirs, so nothing is free.","tr":"If ile takas et. Bu, teklifini onlarınkine bağlar; böylece hiçbir şey bedava olmaz.","fa":"با if بده‌بستان کن. این کار پیشنهادت را به پیشنهاد آن‌ها وابسته می‌کند و چیزی مجانی نمی‌ماند.","ex":"If you ordered 300, we could offer EUR 39."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Trading in a negotiation: If you signed..., we could...","tr":"Pazarlıkta takas: If you signed..., we could...","fa":"بده‌بستان در مذاکره: If you signed..., we could..."},"steps":[{"en":"If + past, then would or could + verb.","tr":"If + geçmiş zaman, sonra would ya da could + fiil.","fa":"در بخش if فعل گذشته می‌آید و در بخش دوم would یا could با فعل ساده.","ex":"If you signed for a year, we could offer EUR 39."},{"en":"Past form, present meaning: an idea, not a promise.","tr":"Geçmiş biçim, şimdiki anlam: bir söz değil, bir fikir.","fa":"فعل گذشته است، ولی منظورت زمان حال است: فقط ایده‌ای را مطرح می‌کنی و قولی نمی‌دهی.","ex":"If we gave you 60 days, ..."},{"en":"No would in the if-part.","tr":"if kısmında would yok.","fa":"در بخش if کلمه‌ی would نمی‌آید.","ex":"If we gave..., not If we would give"},{"en":"What if we + past? suggests a trade softly.","tr":"What if we + geçmiş? bir takası yumuşakça önerir.","fa":"با What if we و فعل گذشته، بده‌بستان را نرم پیشنهاد می‌کنی.","ex":"What if we split the order into three deliveries?"}],"table":{"headers":{"en":["If-part (past)","Other part (would / could)"],"tr":["if kısmı (geçmiş)","Diğer kısım (would / could)"],"fa":["بخش if (گذشته)","بخش دیگر (would / could)"]},"rows":[["If you signed for a year,","we could offer EUR 39."],["If we gave you 60 days,","we would need a higher price."],["If you paid 30% now,","we could start next week."],["What if we","split the order into three deliveries?"]]},"tip":{"en":"Turkish uses '-sak' ('Fiyatı düşürsek imzalar mısınız?') and Persian «اگر ... می‌کردیم» or «اگر ... کنیم», with no past-for-present rule. So learners put would in both halves. English: past in the if-part, would only in the other.","tr":"Türkçede '-sak' kullanırız: 'Fiyatı düşürsek imzalar mısınız?' Burada şimdi için geçmiş biçim kuralı yok; bu yüzden İngilizcede iki yarıya da would konuyor. İngilizcede if kısmına geçmiş biçim, would yalnızca diğer kısma gelir.","fa":"در فارسی می‌گوییم «اگر قیمت را کم کنیم، امضا می‌کنید؟» یا «اگر کم می‌کردیم...». قاعده‌ی «گذشته برای حال» را به این شکل نداریم؛ برای همین خیلی از ما در هر دو بخش جمله would می‌گذاریم. در انگلیسی بخش if گذشته است و would فقط در بخش دیگر می‌آید."},"wrong":"If you would sign today, we could ship in May.","right":"If you signed today, we could ship in May."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Writing it down","tr":"Yazıya dökmek","fa":"توافق را بنویس"},"body":{"en":"Trade more than price: volume, contract length, payment, delivery dates, packaging. Make each concession smaller, so the buyer sees you are near your limit. Never say the limit, or bargaining starts from there. At the end, repeat the deal and send it in writing that day.","tr":"Yalnızca fiyatı değil, miktarı, sözleşme süresini, ödemeyi, teslim tarihlerini ve ambalajı da takas et. Her ödünü küçült ki alıcı sınırına yaklaştığını görsün. Sınırını asla söyleme, yoksa pazarlık oradan başlar. Sonunda anlaşmayı tekrar et ve aynı gün yazılı gönder.","fa":"فقط قیمت را بده‌بستان نکن؛ مقدار، مدت قرارداد، پرداخت، تاریخ تحویل و بسته‌بندی را هم در نظر بگیر. هر امتیاز را کوچک‌تر از قبلی بده تا خریدار بفهمد به آخر خط نزدیک شده‌ای. حد نهایی‌ات را هم نگو، وگرنه چانه‌زنی از همان‌جا شروع می‌شود. در پایان توافق را تکرار کن و همان روز کتبی بفرست."},"phrases":[{"phrase":"What matters most to you?","meaning":{"en":"Finds what to trade.","tr":"Neyin takas edileceğini bulur.","fa":"معلوم می‌کند چه چیزی را بده‌بستان کنی."}},{"phrase":"If you ..., we could ...","meaning":{"en":"Offers a trade.","tr":"Takas önerir.","fa":"بده‌بستان پیشنهاد می‌کند."}},{"phrase":"So, to confirm, ...","meaning":{"en":"Repeats what you agreed.","tr":"Anlaşılanı tekrar eder.","fa":"توافق را تکرار می‌کند."}},{"phrase":"concession","meaning":{"en":"Something you give up to reach an agreement.","tr":"ödün, taviz.","fa":"امتیاز (چیزی که برای توافق از آن می‌گذری)"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Turn a gift into a trade","tr":"Hediyeyi takasa çevir","fa":"هدیه را به بده‌بستان تبدیل کن"},"item":"OK, we can give you 60 days to pay, and free delivery too. Your facts: you can give 60 days if the buyer signs for a full year; delivery stays FCA Izmir.","answer":"If you signed for a full year, we could give you 60 days to pay. Delivery stays FCA Izmir. Can you agree to that?","walk":[{"en":"Never give two things at once for nothing.","tr":"Karşılıksız iki şeyi birden asla verme.","fa":"هیچ‌وقت دو چیز را با هم و بدون گرفتن چیزی در عوض نده."},{"en":"Put your condition first: what do you get?","tr":"Önce koşulunu söyle: sen ne alıyorsun?","fa":"اول شرطت را بگو: در عوض چه می‌گیری؟"},{"en":"Say what stays the same, then ask for a clear answer.","tr":"Neyin aynı kaldığını söyle, sonra net bir cevap iste.","fa":"بگو چه چیزی عوض نمی‌شود، بعد جواب روشن بخواه."}]},"quick":{"prompt":"Your plan if there is no deal tells you when to ___.","options":["walk away","lower the price again","send the catalogue"],"correct":0,"why":{"en":"walk away: if the deal is worse than your plan B, you say no with confidence.","tr":"walk away: anlaşma B planından kötüyse, güvenle hayır dersin.","fa":"جواب walk away است، یعنی از معامله بیرون بیایی. اگر معامله از برنامه‌ی جایگزینت بدتر باشد، با اطمینان نه می‌گویی."}},"remember":{"en":"Nothing for free: if you give, you get. You can now plan a negotiation and offer each concession as a trade.","tr":"Hiçbir şey bedava değil: veriyorsan alırsın. Artık bir pazarlığı planlayabilir ve her ödünü takas olarak sunabilirsin.","fa":"هیچ چیز را مجانی نده: چیزی می‌دهی و چیزی می‌گیری. حالا می‌توانی مذاکره را برنامه‌ریزی کنی و هر امتیاز را به شکل بده‌بستان پیشنهاد بدهی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Testing an idea: Suppose we..., If we were to...","tr":"Bir fikri yoklamak: Suppose we..., If we were to...","fa":"سنجیدن یک ایده: Suppose we... و If we were to..."},"steps":[{"en":"Suppose + past = 'Let's imagine...' (like if).","tr":"Suppose + geçmiş = 'Diyelim ki...' (if gibi).","fa":"بعد از Suppose فعل گذشته می‌آید و معنایش «فرض کنیم...» است.","ex":"Suppose we delivered in three parts, ..."},{"en":"If + were to + base verb: a distant, safe idea.","tr":"If + were to + yalın fiil: uzak ve güvenli bir fikir.","fa":"بعد از If we were to فعل ساده می‌آید و ایده را دور و بی‌خطر نشان می‌دهد.","ex":"If we were to offer 60 days, ..."},{"en":"would goes in the other half, never after Suppose.","tr":"would diğer yarıya gider, asla Suppose'tan sonra değil.","fa":"کلمه‌ی would به بخش دیگر جمله می‌رود و هرگز بعد از Suppose نمی‌آید.","ex":"..., would that help?"}],"table":{"headers":{"en":["Opener","Example"],"tr":["Giriş","Örnek"],"fa":["شروع","مثال"]},"rows":[["Suppose / Supposing + past","Suppose we delivered in three parts, would that help?"],["If + were to + base verb","If we were to offer 60 days, the price would be EUR 41."],["What would you say if + past","What would you say if we added your label?"]]},"body":{"en":"B2: test one idea with Suppose or If we were to before you offer it.","tr":"B2: bir fikri sunmadan önce Suppose ya da If we were to ile yokla.","fa":"مسیر B2: پیش از پیشنهاد دادن یک ایده، آن را با Suppose یا If we were to بسنج."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
